NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'I John'

CHAPTERS = {
    1: {
        1: 'To, kar je bilo od začetka, kar smo slišali, kar smo videli s svojimi lastnimi očmi, kar smo opazovali in so naše roke prijele, Besedo življenja',
        2: '(kajti življenje je bilo jasno pokazano in videli smo ga in pričujemo in vam kažemo to večno življenje, ki je bilo z Očetom in je bilo jasno pokazano nam),',
        3: 'to, kar smo videli in slišali, to oznanjamo vam, da boste tudi vi lahko imeli z nami družbo; in resnično, naša družba je z Očetom in z njegovim Sinom Jezusom Kristusom.',
        4: 'In te stvari vam pišemo, da bo vaše veselje lahko popolno.',
        5: 'To je torej sporočilo, ki smo ga slišali od njega in ga oznanjamo vam, da je Bog svetloba in v njem sploh ni nobene teme.',
        6: 'Če rečemo, da imamo družbo z njim, pa hodimo v temi, lažemo in ne delamo resnice;',
        7: '§ toda če hodimo v svetlobi, kakor je on v svetlobi, imamo družbo drug z drugim in kri Jezusa Kristusa, njegovega Sina, nas očiščuje pred vsakim grehom.',
        8: 'Če rečemo, da nimamo greha, sami sebe zavajamo in resnice ni v nas.',
        9: 'Če priznavamo svoje grehe, je zvest in pravičen, da nam naše grehe odpusti in da nas očisti pred vso nepravičnostjo.',
        10: 'Če rečemo, da nismo grešili, ga naredimo lažnivca in njegove besede ni v nas.',
    },
    2: {
        1: 'Moji mali otroci, te stvari vam pišem, da ne grešite. Če pa katerikoli človek greši, imamo pri Očetu zagovornika, Jezusa Kristusa, pravičnega.',
        2: 'In on je spravna daritev za naše grehe, pa ne samo za naše, ampak tudi za grehe celotnega sveta.',
        3: 'In s tem spoznamo, da ga poznamo, če se ravnamo po njegovih zapovedih.',
        4: 'Kdor pravi: »Poznam ga,« pa se ne drži njegovih zapovedi, je lažnivec in v njem ni resnice.',
        5: 'Toda kdorkoli se drži njegove besede, je v njem Božja ljubezen resnično izpopolnjena; s tem spoznamo, da smo v njem.',
        6: 'Kdor pravi, [da] ostaja v njem, mora tudi sam tako živeti, kakor je živel on.',
        7: '§ Bratje, ne pišem vam nobene nove zapovedi, temveč staro zapoved, ki ste jo imeli od začetka. Stara zapoved je beseda, ki ste jo slišali od začetka.',
        8: 'Ponovno vam pišem novo zapoved, katere beseda je resnična v njem in v vas; zato ker je tema minila in sedaj sije resnična svetloba.',
        9: 'Kdor pravi, [da] je v svetlobi, pa sovraži svojega brata, je v temi celó do sedaj.',
        10: 'Kdor ljubi svojega brata, ostaja v svetlobi in v njem ni nobene priložnosti za spotiko.',
        11: 'Toda kdor sovraži svojega brata, je v temi in hodi po temi in ne ve, kam gre, zato ker mu je ta tema zaslepila njegove oči.',
        12: 'Pišem vam, otročički, ker so vam zaradi njegovega imena odpuščeni vaši grehi.',
        13: 'Pišem vam, očetje, ker ste spoznali njega, ki je od začetka. Pišem vam, mladeniči, ker ste premagali zlobnega. Pišem vam, majhni otroci, ker ste spoznali Očeta.',
        14: 'Pisal sem vam, očetje, ker ste spoznali njega, ki je od začetka. Pisal sem vam, mladeniči, ker ste močni in Božja beseda ostaja v vas in ste premagali zlobnega.',
        15: 'Ne ljubite sveta niti stvari, ki so v svetu. Če katerikoli človek ljubi svet, v njem ni Očetove ljubezni.',
        16: 'Kajti vse, kar je v svetu, poželenje mesa, poželenje oči in napuh življenja, ni od Očeta, temveč od sveta.',
        17: 'In svet mineva in njegovo poželenje; kdor pa izpolnjuje Božjo voljo, ostaja na veke.',
        18: 'Majhni otroci, poslednji čas je in kakor ste slišali, da bo prišel antikrist, je celó sedaj tam mnogo antikristov; po čemer vemo, da je poslednji čas.',
        19: 'Izšli so od nas, toda niso bili od nas; kajti če bi bili od nas, bi brez dvoma ostali z nami, toda odšli so ven, da bi bili lahko jasno prikazani, da niso bili vsi od nas.',
        20: 'Toda vi imate maziljenje od Svetega in poznate vse stvari.',
        21: 'Nisem vam pisal, ker ne poznate resnice, temveč ker jo poznate in da nobena laž ni iz resnice.',
        22: 'Kdo je lažnivec razen, kdor zanika, da Jezus je Kristus? Ta je antikrist, ki zanika Očeta in Sina.',
        23: 'Kdorkoli zanika Sina, ta isti nima Očeta; [toda] kdor priznava Sina, ima tudi Očeta.',
        24: 'Naj torej v vas ostaja to, kar ste slišali od začetka. Če bo to, kar ste slišali od začetka, ostalo v vas, boste tudi vi ostali v Sinu in v Očetu.',
        25: 'In to je obljuba, ki nam jo je obljubil, celó večno življenje.',
        26: 'Te stvari sem vam napisal glede teh, ki vas zapeljujejo.',
        27: 'Toda maziljenje, ki ste ga prejeli od njega, ostaja v vas in ne potrebujete, da vas katerikoli človek uči. Toda kakor vas isto maziljenje uči o vseh stvareh in je resnično in ni laž in celo tako kakor vas je poučilo, boste ostali v njem.',
        28: 'In sedaj, majhni otroci, ostanite v njem, da ko se bo prikazal, bomo lahko imeli zaupanje in ob njegovem prihodu ne bomo osramočeni pred njim.',
        29: 'Če veste, da je pravičen, spoznavate, da je vsak, kdor ravna pravično, rojen iz njega.',
    },
    3: {
        1: '§ Glejte, kakšno vrsto ljubezni nam je podelil Oče, da naj bi bili imenovani Božji sinovi; zato nas svet ne spoznava, ker ni spoznal njega.',
        2: 'Ljubljeni, sedaj smo Božji sinovi, ni pa se še pokazalo, kaj bomo; toda vemo, da ko se bo prikazal, bomo podobni njemu, kajti videli ga bomo, kakršen je.',
        3: 'In vsak človek, ki ima to upanje vanj, se očiščuje, celó kakor je on čist.',
        4: 'Kdorkoli zagreši greh, prestopa tudi postavo, kajti greh je prekršitev postave.',
        5: 'In vi veste, da je bil jasno pokazan, da odvzame naše grehe; in v njem ni greha.',
        6: 'Kdorkoli ostaja v njem, ne greši. Kdorkoli pa greši, ga ni videl niti ga ni spoznal.',
        7: 'Majhni otroci, naj vas noben človek ne zavede. Kdor ravna pravično, je pravičen, celó kakor je pravičen on.',
        8: 'Kdor zagreši greh, je od hudiča, kajti hudič greši od začetka. Zaradi tega namena je bil jasno pokazan Božji Sin, da bi lahko uničil hudičeva dela.',
        9: 'Kdorkoli je rojen iz Boga, ne stori greha, kajti njegovo seme ostaja v njem; in ne more grešiti, ker je rojen iz Boga.',
        10: 'V tem so prikazani Božji otroci in hudičevi otroci: kdorkoli ne dela pravičnosti, ni od Boga niti kdor ne ljubi svojega brata.',
        11: 'Kajti to je sporočilo, ki ste ga slišali od začetka, da naj ljubimo drug drugega.',
        12: 'Ne kakor Kajn, ki je bil od tega zlobnega in je usmrtil svojega brata. In zakaj ga je usmrtil? Ker so bila njegova lastna dela hudobna, njegovega brata pa pravična.',
        13: 'Ne čudite se, moji bratje, če vas svet sovraži.',
        14: 'Mi vemo, da smo iz smrti prešli v življenje, ker ljubimo brate. Kdor svojega brata ne ljubi, ostaja v smrti.',
        15: 'Kdorkoli sovraži svojega brata, je morilec; in veste, da noben morilec nima večnega življenja, ki [bi] ostajalo v njem.',
        16: 'S tem zaznavamo Božjo ljubezen, ker je svoje življenje dal za nas, in mi moramo svoja življenja dati za brate.',
        17: 'Toda kdorkoli ima dobrine tega sveta in vidi svojega brata v potrebi in pred njim zapre svoja čustva sočutja, kako v njem prebiva Božja ljubezen?',
        18: 'Moji majhni otroci, ne ljubimo z besedo niti z jezikom; temveč v dejanju in v resnici.',
        19: 'In s tem vemo, da smo iz resnice in bomo svoja srca potrdili pred njim.',
        20: 'Kajti če nas naše srce obsoja, je Bog večji kakor naše srce in pozna vse stvari.',
        21: 'Ljubljeni, če nas naše srce ne obsoja, potem imamo zaupanje do Boga.',
        22: 'In karkoli prosimo, od njega prejmemo, ker se ravnamo po njegovih zapovedih in delamo te stvari, ki so všečne v njegovih očeh.',
        23: 'In to je njegova zapoved: »Da naj verujemo v ime njegovega Sina Jezusa Kristusa in ljubimo drug drugega,« kakor nam je dal zapoved.',
        24: 'In kdor se ravna po njegovih zapovedih, prebiva v njem in on v njem. In zaradi tega vemo, da on ostaja v nas, po Duhu, ki nam ga je dal.',
    },
    4: {
        1: 'Ljubljeni, ne verjemite vsakemu duhu, temveč duhove preizkušajte, ali so od Boga, ker je mnogo lažnih prerokov odšlo v svet.',
        2: 'S tem prepoznate Božjega Duha: »Vsak duh, ki priznava, da je Jezus Kristus prišel v mesu, je od Boga;',
        3: '§ in noben duh, ki ne priznava, da je Jezus Kristus prišel v mesu, ni od Boga; in to je ta duh antikrista, o katerem ste slišali, da naj bi prišel; in je celó že sedaj na svetu.«',
        4: 'Vi ste od Boga, majhni otroci in ste jih premagali, ker je večji tisti, ki je v vas, kakor ta, ki je v svetu.',
        5: 'Oni so od sveta; zaradi tega govorijo o svetu in svet jih posluša.',
        6: 'Mi [pa] smo od Boga; kdor pozna Boga, nas posluša, kdor [pa] ni od Boga, nas ne posluša. S tem spoznamo duha resnice in duha zmote.',
        7: 'Ljubljeni, ljubimo drug drugega, kajti ljubezen je od Boga, in vsak, kdor ljubi, je rojen iz Boga in pozna Boga.',
        8: 'Kdor ne ljubi, ne pozna Boga, kajti Bog je ljubezen.',
        9: 'V tem je bila do nas jasno pokazana Božja ljubezen, zato ker je ta Bog poslal svojega edinorojenega Sina v svet, da bi mi lahko živeli po njem.',
        10: 'V tem je ljubezen, ne da smo mi ljubili Boga, temveč, da nas je on ljubil in poslal svojega Sina, da postane spravna daritev za naše grehe.',
        11: 'Ljubljeni, če nas je Bog tako ljubil, bi morali tudi mi ljubiti drug drugega.',
        12: 'Noben človek nikoli ni videl Boga. Če ljubimo drug drugega, Bog prebiva v nas in je njegova ljubezen izpopolnjena v nas.',
        13: 'S tem vemo, da prebivamo v njem in on v nas, ker nam je dal od svojega Duha.',
        14: 'In videli smo in pričujemo, da je Oče poslal Sina, da bi bil Odrešenik sveta.',
        15: 'Kdorkoli bo priznal, da je Jezus Božji Sin, Bog prebiva v njem in on v Bogu.',
        16: 'In mi smo spoznali in verovali ljubezni, ki jo ima Bog do nas. Bog je ljubezen in kdor prebiva v ljubezni, prebiva v Bogu in Bog v njem.',
        17: 'V tem se je naša ljubezen dovršila, da imamo lahko srčnost na dan sodbe; ker kakor je on, tako smo mi na tem svetu.',
        18: 'V ljubezni ni nobenega strahu, temveč popolna ljubezen izganja strah; ker strah vsebuje muko. Kdor se boji, ni izpopolnjen v ljubezni.',
        19: 'Mi ga ljubimo, ker je najprej on ljubil nas.',
        20: 'Če človek reče: »Ljubim Boga,« pa sovraži svojega brata, je lažnivec; kajti kdor ne ljubi svojega brata, ki ga je videl, kako lahko ljubi Boga, ki ga ni videl?',
        21: 'In od njega imamo to zapoved: »Da kdor ljubi Boga, ljubi tudi svojega brata.«',
    },
    5: {
        1: 'Kdorkoli veruje, da Jezus je Kristus, je rojen iz Boga; in vsak, kdor ljubi tistega, ki je zaplodil, ljubi tudi tistega, ki je zaplojen od njega.',
        2: 'Da ljubimo Božje otroke, spoznamo s tem, ko ljubimo Boga in se ravnamo po njegovih zapovedih.',
        3: 'Kajti to je Božja ljubezen, da se ravnamo po njegovih zapovedih; in njegove zapovedi niso mučne.',
        4: 'Kajti karkoli je rojeno iz Boga, premaga svet; in to je zmaga, ki premaga svet, celó naša vera.',
        5: 'Kdo je tisti, ki premaga svet, če ne tisti, ki veruje, da je Jezus Božji Sin?',
        6: 'To je on, ki je prišel z vodo in krvjo, celó Jezus Kristus; ne samo z vodo, temveč z vodo in krvjo. In to je Duh, ki prinaša pričevanje, ker Duh je resnica.',
        7: '§ Kajti trije so, ki pričujejo na nebu: Oče, Beseda in Sveti Duh; in ti trije so eno.',
        8: '§ In trije so, ki pričujejo na zemlji: Duh in voda in kri; in ti trije se strinjajo v enem.',
        9: 'Če smo sprejeli pričevanje od ljudi, je pričevanje od Boga večje, kajti to je pričevanje Boga, ki je pričeval o svojem Sinu.',
        10: 'Kdor veruje v Božjega Sina, ima pričevanje v sebi. Kdor pa ne veruje Bogu, ga je storil za lažnivca, ker ne veruje zapisu, ki ga je Bog dal o svojem Sinu.',
        11: 'In to je zapis, da nam je Bog dal večno življenje in to življenje je v njegovem Sinu.',
        12: 'Kdor ima Sina, ima življenje; kdor pa nima Božjega Sina, nima življenja.',
        13: '§ Te besede sem napisal vam, ki verujete v ime Božjega Sina; da boste lahko vedeli, da imate večno življenje in da lahko verujete v ime Božjega Sina.',
        14: 'In to je zaupanje, ki ga imamo v njem, da če prosimo katerokoli stvar, glede na njegovo voljo, nas on usliši.',
        15: 'In če vemo, da nas sliši, karkoli prosimo, vemo, da imamo prošnje, ki smo jih želeli od njega.',
        16: 'Če katerikoli človek vidi svojega brata grešiti [z] grehom, ki ni za smrt, bo prosil in on mu bo dal življenje, za tiste, ki ne grešijo za smrt. Obstaja greh za smrt; ne pravim, da naj prosi zanj.',
        17: 'Vsa nepravičnost je greh; obstaja pa greh, ki ni za smrt.',
        18: '§ Vemo, da kdorkoli je rojen iz Boga, ne greši; temveč kdor je rojen iz Boga, sebe varuje in ta zlobni se ga ne dotika.',
        19: 'In mi vemo, da smo od Boga, celoten svet pa leži v zlobnosti.',
        20: 'In mi vemo, da je Božji Sin prišel ter nam dal razumevanje, da bi lahko spoznali tistega, ki je resničen in mi smo v njem, ki je resničen, celó v njegovem Sinu Jezusu Kristusu. Ta je resničen Bog in večno življenje.',
        21: '§ Majhni otroci, varujte se pred maliki. Amen.',
    },
}
